// Prepare input for Ragnarok RAG Agent from webhook body
const body = $input.item.json.body || {};
const query = body.query || body.message || body.text || '';
const kbIds = body.kb_ids || [];
const projectId = body.project_id || 'aisha';
const lang = body.lang || 'cs-CZ';

if (!query) {
  return { json: { error: 'Missing query parameter in request body' } };
}

return {
  json: {
    chatInput: query,
    session_id: body.session_id || 'ragnarok-' + Date.now(),
    kb_ids: kbIds,
    project_id: projectId,
    lang: lang,
    metadata: {
      source: 'webhook',
      agent: 'ragnarok',
      timestamp: new Date().toISOString(),
      user_id: body.user_id || null,
    }
  }
};

// MCP Tool: search_ragnarok
const query = $input.item.json.query || $input.item.json || '';
let args;
try {
  args = typeof query === 'string' ? JSON.parse(query) : query;
} catch {
  args = typeof query === 'string' && query.length > 0 ? { query } : {};
}

const mcpUrl = ($env?.AISHA_POSTGREST_URL || '') + '/functions/v1/mcp-knowledge-server';
const token = $env?.AISHA_ACCESS_TOKEN || $env?.AISHA_KEYCLOAK_ACCESS_TOKEN || '';

const rpcBody = JSON.stringify({
    jsonrpc: '2.0',
    id: Date.now(),
    method: 'tools/call',
    params: { name: 'search_ragnarok', arguments: args }
  });

let data;
try {
  if (typeof fetch === 'function') {
    const res = await fetch(mcpUrl, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json', 'Authorization': 'Bearer ' + token },
      body: rpcBody
    });
    data = await res.json();
  } else {
    const https = require('https');
    const url = new URL(mcpUrl);
    data = await new Promise((resolve, reject) => {
      const req = https.request({
        hostname: url.hostname,
        port: url.port || 443,
        path: url.pathname,
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'Authorization': 'Bearer ' + token,
          'Content-Length': Buffer.byteLength(rpcBody)
        }
      }, res => {
        let body = '';
        res.on('data', c => body += c);
        res.on('end', () => {
          try { resolve(JSON.parse(body)); }
          catch { reject(new Error('Invalid JSON response: ' + body.substring(0, 200))); }
        });
      });
      req.on('error', reject);
      req.write(rpcBody);
      req.end();
    });
  }
} catch (e) {
  return 'MCP Tool Error: ' + (e.message || String(e));
}
if (data.error) return 'MCP Error: ' + (data.error.message || JSON.stringify(data.error));
if (data.result?.content) {
  return data.result.content.map(c => c.type === 'text' ? c.text : JSON.stringify(c)).join('\n');
}
return JSON.stringify(data.result || data);

